#pragma once
#define BATTERIES_RADIX_ENCODE_HPP

#include <batteries/assert.hpp>
#include <batteries/int_types.hpp>
#include <batteries/math.hpp>
#include <batteries/status.hpp>

#include <array>
#include <type_traits>

namespace batt {

template <typename Encoding, typename UIntT>
char* radix_encode(UIntT value, char* buffer, usize len) noexcept
{
    static_assert(std::is_integral_v<UIntT>);
    static_assert(std::is_unsigned_v<UIntT>);

    static const std::array<char, Encoding::kRadix>& chars = Encoding::get_chars();

    constexpr usize kRadixBits = Encoding::kRadixBits;
    constexpr usize kBits = (sizeof(UIntT) * 8);
    constexpr usize kOutputLength = (kBits + kRadixBits - 1) / kRadixBits;
    constexpr usize kMask = (usize{1} << kRadixBits) - 1;

    BATT_CHECK_GE(len, kOutputLength);

    char* out = &buffer[kOutputLength];
    for (usize i = 0; i < kOutputLength; ++i) {
        --out;
        *out = chars[value & kMask];
        value >>= kRadixBits;
    }

    return out;
}

//=#=#==#==#===============+=+=+=+=++=++++++++++++++-++-+--+-+----+---------------

template <bool kLowerCase = true>
struct HexEncoding {
    static constexpr usize kRadix = 16;
    static constexpr usize kRadixBits = 4;

    static const std::array<char, 16>& get_chars() noexcept
    {
        static const std::array<char, 16>& cache_ = []() -> auto& {
            static std::array<char, 16> cache_;

            constexpr usize kZero = 0;
            constexpr usize kA = 10;

            for (usize i = 0; i < 10; ++i) {
                cache_[i + kZero] = '0' + i;
            }
            for (usize i = 0; i < 6; ++i) {
                if constexpr (kLowerCase) {
                    cache_[i + kA] = 'a' + i;
                } else {
                    cache_[i + kA] = 'A' + i;
                }
            }

            return cache_;
        }();

        return cache_;
    }
};

template <typename UIntT>
inline char* format_hex(UIntT value, char* buffer, usize len) noexcept
{
    return radix_encode<HexEncoding<>>(value, buffer, len);
}

template <typename UIntT>
inline StatusOr<UIntT> parse_hex(const char* buffer, usize len) noexcept
{
    const char* next = buffer;
    const char* last = buffer + len;

    UIntT value = 0;

    for (; next != last; ++next) {
        const char ch = *next;
        if ('0' <= ch && ch <= '9') {
            value = (value << 4) | (ch - '0');
        } else if ('A' <= ch && ch <= 'F') {
            value = (value << 4) | (ch - 'A' + 0xa);
        } else if ('a' <= ch && ch <= 'f') {
            value = (value << 4) | (ch - 'a' + 0xa);
        } else {
            return {batt::StatusCode::kInvalidArgument};
        }
    }

    return {value};
}

}  //namespace batt
